css:
#tongsci1-3-3-4-tx3d .tx-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: radial-gradient(circle at 30% 45%, #f8f2fd 0%, #eef0f7 50%, #dfe6ef 100%); }
#tongsci1-3-3-4-tx3d .tx-stage canvas { touch-action: none; cursor: grab; }
#tongsci1-3-3-4-tx3d .tx-stage .now-chip { top: auto; bottom: 14px; max-width: calc(100% - 32px); }
#tongsci1-3-3-4-tx3d .tx-tools { position: absolute; right: 14px; top: 12px; display: flex; gap: 8px; z-index: 3; }
#tongsci1-3-3-4-tx3d .tx-tools .btn { font-size: 19px !important; padding: 8px 14px !important; }
#tongsci1-3-3-4-tx3d .tx-tag { pointer-events: auto; cursor: pointer; font-size: 18px; padding: 2px 10px; transition: opacity .25s, background .25s; }
#tongsci1-3-3-4-tx3d .tx-tag:focus-visible { outline: 4px solid var(--hl); }
#tongsci1-3-3-4-tx3d .tx-tag.pulse { background: var(--hl); animation: tongsci1-3-3-4-tx3d--tx-pulse 1.4s ease-in-out infinite; }
@keyframes tongsci1-3-3-4-tx3d--tx-pulse { 50% { box-shadow: 0 0 0 7px color-mix(in srgb, var(--hl) 75%, transparent); } }
#tongsci1-3-3-4-tx3d .tx-gene { border-color: #a07800; }
#tongsci1-3-3-4-tx3d .tx-rna { color: #12665d; border-color: #2a9d8f; }
#tongsci1-3-3-4-tx3d .tx-side { pointer-events: none; cursor: default; font-size: 16px; color: #4a3a6e; border-color: #8a72b8; background: rgba(246, 240, 252, .9); }
#tongsci1-3-3-4-tx3d .tx-stay { pointer-events: none; font-size: 15px; padding: 1px 9px; color: #6b3d00; border: 1.5px dashed #a07800; background: rgba(255, 249, 225, .9); transition: background .2s, transform .2s; }
#tongsci1-3-3-4-tx3d .tx-stay.on { background: var(--hl); font-size: 18px; }
#tongsci1-3-3-4-tx3d .tx-cod { pointer-events: none; font-size: 18px; background: #fff; border-color: #3b3f8c; color: #1d2433; }
#tongsci1-3-3-4-tx3d .tx-prot { font-size: 19px; color: #1d2433; border-color: var(--ink); background: #f3e6fb; }
#tongsci1-3-3-4-tx3d .tx-tray { flex-wrap: nowrap; }
#tongsci1-3-3-4-tx3d .tx-flow { display: flex; align-items: center; gap: 8px; flex: 1 1 auto; min-width: 0; }
#tongsci1-3-3-4-tx3d .tx-flow span { font: 800 22px var(--f-display); padding: 6px 16px; border: 2px solid var(--ink-3); border-radius: 10px; color: var(--ink-3); background: var(--paper-2); transition: background .3s, color .3s; }
#tongsci1-3-3-4-tx3d .tx-flow span.on { color: var(--ink); border-color: var(--ink); }
#tongsci1-3-3-4-tx3d .tx-flow span[data-f="dna"].on { background: #e6dcf6; }
#tongsci1-3-3-4-tx3d .tx-flow span[data-f="rna"].on { background: #d3efe9; }
#tongsci1-3-3-4-tx3d .tx-flow span[data-f="prot"].on { background: #fde3d8; }
#tongsci1-3-3-4-tx3d .tx-flow i { font: 700 16px var(--f-body); font-style: normal; color: var(--ink-3); white-space: nowrap; position: relative; padding-right: 16px; }
#tongsci1-3-3-4-tx3d .tx-flow i::after { content: "▶"; position: absolute; right: 0; top: 0; font-size: 13px; line-height: 1.5; }
#tongsci1-3-3-4-tx3d .tx-flow i.run { color: var(--accent); animation: tongsci1-3-3-4-tx3d--tx-run 1s ease-in-out infinite; }
@keyframes tongsci1-3-3-4-tx3d--tx-run { 50% { opacity: .45; } }
#tongsci1-3-3-4-tx3d .tx-panel { gap: 10px; }
#tongsci1-3-3-4-tx3d .tx-out { margin: 0; font-size: 20px; line-height: 1.45; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 7px 14px; min-height: 4.4em; flex: none; }
#tongsci1-3-3-4-tx3d .tx-seq { width: 100%; border-collapse: collapse; table-layout: fixed; flex: none; background: var(--paper-2); border: 2px solid var(--ink); font: 600 16px/1.2 var(--f-body); }
#tongsci1-3-3-4-tx3d .tx-seq th { width: 78px; font: 800 16px/1.15 var(--f-body); text-align: left; padding: 4px 6px; background: color-mix(in srgb, var(--ink) 5%, var(--paper-2)); border: 1.5px solid var(--ink-3); }
#tongsci1-3-3-4-tx3d .tx-seq th small { display: block; font: 600 12px var(--f-body); color: var(--ink-3); }
#tongsci1-3-3-4-tx3d .tx-seq td { border: 1.5px solid var(--rule, #c9ccd3); padding: 4px 1px; text-align: center; font-family: var(--f-mono, monospace); letter-spacing: .02em; }
#tongsci1-3-3-4-tx3d .tx-seq tr.r0 td { color: #5a2f94; }
#tongsci1-3-3-4-tx3d .tx-seq tr.r1 td { color: #0f6b60; font-weight: 800; }
#tongsci1-3-3-4-tx3d .tx-seq tr.r2 td { font: 700 13px/1.15 var(--f-body); letter-spacing: -.04em; word-break: keep-all; height: 2.6em; }
#tongsci1-3-3-4-tx3d .tx-seq tr.r2 i { font-style: normal; display: block; }
#tongsci1-3-3-4-tx3d .tx-seq tr.r2 i::before { content: ""; display: block; width: 14px; height: 14px; margin: 0 auto 2px; border-radius: 50%; background: var(--c, #999); }
#tongsci1-3-3-4-tx3d .tx-seq td.cur { background: color-mix(in srgb, var(--hl) 55%, #fff); }
#tongsci1-3-3-4-tx3d .tx-key { margin: 0; font-size: 17px; color: var(--ink-2); flex: none; }
#tongsci1-3-3-4-tx3d .tx-key span { font-weight: 800; padding: 0 5px; border-radius: 5px; color: #1d2433; }
#tongsci1-3-3-4-tx3d .tx-key .b-a { background: #ffe98a; }
#tongsci1-3-3-4-tx3d .tx-key .b-g { background: #bfe9c9; }
#tongsci1-3-3-4-tx3d .tx-key .b-c { background: #c4def8; }
#tongsci1-3-3-4-tx3d .tx-key .b-t { background: #f9d1a2; }
#tongsci1-3-3-4-tx3d .tx-key .b-u { background: #f8c6de; }
#tongsci1-3-3-4-tx3d.u-done .tx-out { display: none; }
@media (prefers-reduced-motion: reduce) {
  #tongsci1-3-3-4-tx3d .tx-tag.pulse, #tongsci1-3-3-4-tx3d .tx-flow i.run { animation: none; }
}
#tongsci1-3-3-4-tx3d .body.sim { grid-template-columns: 1000px minmax(0, 1fr); }

